operations.exampleQuery:
query Pharma_assessEligibility(
  $origin: Pharma_AuthorizationOrigin!,
  $storeCode: String!,
  $productCode: String!,
  $customerCode: String!
) {
  Pharma_assessEligibility(
    origin: $origin, storeCode: $storeCode,
    productCode: $productCode, customerCode: $customerCode
  ) {
    validationResult { status message errors { message } }
    eligibilityAssessment { belongsToIndustryProgram programDescription programCode productDescription }
    registrationPolicy { requiresBeneficiaryRegistration isRegistered allowedOrigins }
    dependents { id name birth gender holder }
  }
}

mutation Pharma_signUpProgramBeneficiary(
  $input: Pharma_RegisterBeneficiaryRequest!
) {
  Pharma_signUpProgramBeneficiary(input: $input) {
    status
    message
    errors { message }
  }
}

mutation Pharma_signUpProgramBeneficiaryDependent(
